input.content:
extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH = "user://save.json"

func _ready() -> void:
	get_tree().auto_accept_quit = false
	load_game()

func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		save()
		get_tree().quit()

func add_coin() -> void:
	_count += 1
	coin_changed.emit(_count)

func get_count() -> int:
	return _count

func save() -> void:
	var file = FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify({"count": _count}))
		file.close()

func load_game() -> void:
	if FileAccess.file_exists(SAVE_PATH):
		var file = FileAccess.open(SAVE_PATH, FileAccess.READ)
		if file:
			var json_text = file.get_as_text()
			var json = JSON.new()
			var error = json.parse(json_text)
			if error == OK:
				var data = json.data
				if data is Dictionary and data.has("count"):
					_count = int(data["count"])
			file.close()
		coin_changed.emit(_count)

extends CharacterBody2D

@export var speed := 300.0

func _physics_process(_delta: float) -> void:
	var direction := Vector2(
		Input.get_axis("ui_left", "ui_right"),
		Input.get_axis("ui_up", "ui_down")
	)
	velocity = direction.normalized() * speed
	move_and_slide()

extends Area2D

signal collected

func _ready() -> void:
	body_entered.connect(_on_body_entered)

func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player":
		collected.emit()
		Inventory.add_coin()
		queue_free()

extends CanvasLayer

@onready var label := $Label

func _ready() -> void:
	Inventory.coin_changed.connect(_on_coin_changed)
	label.text = "Coins: %d" % Inventory.get_count()

func _on_coin_changed(new_count: int) -> void:
	label.text = "Coins: %d" % new_count
